use crate::domains::kernel_opt::corpus::KernelRule;

pub fn entries() -> Vec<KernelRule> {
    vec![
        KernelRule {
            rule_id: "batch-pool-read-makes-serial-readahead-redundant".to_string(),
            gpu_concept: "When the very next consumer of a byte range is a QUEUED PARALLEL READ POOL (a pread worker fan-out over unique offsets), an advisory read-ahead hint (fcntl F_RDADVISE per chunk, posix_fadvise WILLNEED, mmap touched ahead) for those SAME ranges issued immediately before the pool starts is DUPLICATION, not prefetch: the hint enqueues real read I/O that competes with and delays the pool's own better-shaped parallel reads -- the pool's reads should be the FIRST I/O for those pages. The dispatch boundary is not 'is read-ahead useful?' but 'is there a queued parallel reader of these identical bytes behind this point?'; YES at the call site => delete the hint (definitionally duplicate work, determinable statically at the call site -- no prediction involved). KEEP the hint on sibling paths with no pool behind them: single-stream decode-side loads (one expert at a time) and pending-load installs still benefit -- the rule is per-callsite, never per-subsystem. Suggest-only fix class (a deletion at one call site; a parse-only proposer cannot see that a pool consumes the same ranges). Regime: batch cold reads of expert/weight shards feeding a parallel pread pool on the cold-storage path. Gain SOURCE-REPORTED (M5 Max, GLM Q4 initial/continued prefill 73/77 -> 93/97 tok/s, ~+27%, identical full frontier logits -- byte-identity gate in-commit); honest NotBenchable here (no model files; not our silicon). Distinct from first-readback-pays-queue-drain (GPU readback sync cost; this is host disk-I/O duplication), from request-arrival-work-asks-reuse-state-first (predicted work on warm turns; here the very next consumer reads the identical bytes -- no prediction), from kv-window-device-resident-ring-append (device residency of a mutable operand; this is the cold-storage host path), and from coalesce-nearby-reads-bounded-gap-cacheability-gated (B94 merges NEARBY ranges into fewer syscalls for a single consumer; this removes a SECOND issuer for the SAME ranges when a pool is the consumer -- the two compose: the pool coalesces per-worker, the hint goes). Source: antirez/ds4 @ c0a6119f (MIT) -- commit d6580a5 'Let parallel Metal prefill reads run without serial read-ahead' (ds4_metal.m 2+/6-): the deleted calls ds4_gpu_stream_expert_readahead_range(unique_gate_offsets[u], gate_expert_bytes) + the up/down twins immediately before ds4_gpu_stream_expert_cache_prepare_load_buffers hands the batch to the worker pool, replaced by the cost comment 'The worker pool reads this entire batch below. Serial read-ahead here waits for the same pages before parallel I/O can begin.' (ds4_metal.m:17482-17483 at the pin); the hint itself is fcntl(F_RDADVISE) per chunk (ds4_metal.m:13150-13182); the KEPT hint sites: decode-side single-expert loads (ds4_metal.m:16137-16139) + pending-load installs (:16586). Batch 123 / Plan 103 / Research 146.".to_string(),
            ref_shape: "// host thread issues advisory read-ahead per range, THEN hands the\n// same ranges to a pread worker pool -- the hint's I/O serializes ahead\n// of the pool.\nfn prepare_selected_batch(offsets: &[u64], len: u64, pool: &ReadPool) {\n    for &off in offsets {\n        readahead_range(off, len); // F_RDADVISE: real I/O, enqueued NOW\n    }\n    pool.read_all(offsets, len); // waits behind the hint's own reads\n}\n".to_string(),
            opt_pattern: "// the pool IS the read-ahead: no hint when a queued parallel reader\n// consumes the identical ranges; hints stay on pool-less sibling paths.\nfn prepare_selected_batch(offsets: &[u64], len: u64, pool: &ReadPool) {\n    // (no readahead here -- the worker pool below reads these bytes first;\n    //  a serial hint would only delay the parallel phase)\n    pool.read_all(offsets, len);\n}\n\nfn decode_load_single(off: u64, len: u64) -> Vec<u8> {\n    readahead_range(off, len); // KEPT: no pool behind this path\n    blocking_read(off, len)\n}\n".to_string(),
        },
        KernelRule {
            rule_id: "cold-large-prefill-whole-layer-lookahead-over-partial-cache".to_string(),
            gpu_concept: "Read-pattern dispatch for expert/MoE weight streaming keyed on (position-or-layout, CHUNK SIZE, CACHE TEMPERATURE) with EXACTLY ONE layer of read-ahead: when a prefill chunk routes to MOST experts of a layer (>= 256 tokens is the source's measured threshold), row-addressed reads through the expert index degenerate into reading nearly the whole tensor at index granularity -- near-random access -- so WHOLE-LAYER sequential reads win (full sequential I/O throughput), and exactly ONE next-layer read is started while the current layer computes (lookahead depth 1: keeps the SSD busy during compute WITHOUT over-committing memory to N-layer prefetch). The regime test is three-way: position (first chunk of a session) OR layout (generic quantized routed-MoE) decides the PATH FAMILY; token count decides streaming vs cached dispatch; cache temperature (a continued append's cache is cold for newly-routed experts even mid-session) decides within the family -- position alone is the WRONG key (a continued 8K-token append is a cold-cache all-experts chunk that must stream whole layers too). Complementary cached path: prompt chunks and small appends whose working set is already cache-resident stay on row-addressed cached dispatch (the ladder's other arm), and typed layouts with good cache reuse keep the selected path -- the ladder is cold/large -> whole-layer+lookahead-1, small/warm-fit -> cache-indirect, and the boundary is MEASURED, not assumed. Suggest-only fix class (a dispatch-gate restructure). Regime: SSD/streaming weight feeds for prefill. Gain SOURCE-REPORTED (M5 Max: 8K/4K-append prefill 63.23/61.56 -> 90.70/84.31 tok/s; 512-token append 14.64 -> 26.01 tok/s at a FIXED 35.36 GiB cache; 154,880 frontier logits byte-identical); honest NotBenchable here. Distinct from row-addressable-operand-index-not-full-tensor-map (that rule: address only the rows you need -- this is the named COMPLEMENT, the regime where the rows you need are ~all rows and index-granular random access loses to sequential; the 256-token + cache-temperature boundary between them is the decision content), from prefill-chunk-command-buffer-capacity-coupled (scratch capacity coupling; this is read granularity + lookahead depth), from scratch-bank-isolates-one-shot-operands-from-hot-cache (bank lifetime isolation vs read-pattern selection), and from kv-block-streaming (KV blocks, not weight tensors). Source: antirez/ds4 @ c0a6119f (MIT) -- commits 6ccc1e7 'Use the available Metal cache and overlap the first GLM streaming prefill' + 437dbcb 'Read full IQ2 GLM layers ahead during large continued prefills' (ds4.c): the gate before (437dbcb^ ds4.c:49723-49730) keyed on pos0 == 0 ALONE ('The first large chunk has a cold cache and touches most experts. Read complete layers, keeping one read ahead; later chunks reuse the cache.'), after (pin ds4.c:49820-49829) '(pos0 == 0 || (!g->glm53 && glm_graph_layer_uses_generic_routed_moe(&weights->layer[DS4_N_LEADING_DENSE]))) && n_tokens >= 256u ...' with the comment 'Generic IQ2 GLM benefits from sequential layer reads on large continued chunks too. Keep the typed Flash path's selected-expert cache reuse.'; the lookahead (pin ds4.c:49987-49991): 'if (ok && layer_prepare && il < g->layer_end) { ok = metal_graph_stream_prepare_start_if_needed(NULL, model, weights, il + 1u, n_tokens, false, true, false, false, &layer_prepare_slot, 1); }' -- one layer, started only when more layers remain; the cold-chunk cache seeding glm_graph_seed_streaming_expert_cache_from_full_layer (pin ds4.c:46330, recent-32-token recency boost '+= count' then prompt-frequency fill). Batch 123 / Plan 103 / Research 146.".to_string(),
            ref_shape: "// whole-layer streaming decided by POSITION alone: first chunk streams\n// layers; every continued chunk -- even a cold-cache 8K append that routes\n// to nearly every expert -- degrades to per-expert index reads.\nlet full_layer = pos0 == 0 && n_tokens >= 256;\nif full_layer {\n    stream_whole_layers(no_lookahead); // or worse: per-tensor, no overlap\n} else {\n    for expert in routed_experts {\n        read_row_addressed(expert)?; // ~random at index granularity\n    }\n}\n".to_string(),
            opt_pattern: "// the key is (position OR generic-layout) AND chunk-size AND cache\n// temperature; exactly ONE next-layer read overlaps current-layer compute.\nlet full_layer = (pos0 == 0 || layout.is_generic_routed_moe())\n    && n_tokens >= 256\n    && stream_prefill_enabled;\nif full_layer {\n    for il in layer_range {\n        prepare_layer(il)?;          // sequential whole-layer reads\n        if il + 1 < layer_end {\n            prepare_start(il + 1)?;  // ONE layer of lookahead -- no more\n        }\n        compute_layer(il);\n    }\n} else {\n    dispatch_cached_or_selected();   // warm small chunks keep cache reuse\n}\n".to_string(),
        },
        KernelRule {
            rule_id: "static-seed-priority-bounded-to-observed-scale".to_string(),
            gpu_concept: "When a STATIC preload/warm list (a built-in hot ranking) and RUNTIME observation counters (decayed hit/miss frequencies) share ONE eviction-priority namespace, the static seeds must enter at a magnitude COMPARABLE to what the observation counters can reach -- compress the list rank into a bounded band (the source: `1u + 31ull * remaining / total`, i.e. 1..=31) -- else no amount of observed evidence can ever out-rank a seed and the cache is a permanent dictatorship of the cold-start list: session-specific expert distributions never displace static entries, fixed-code re-reads never fall. The banding preserves list ORDER within the band (rank 1 still seeds above rank 31) while capping its VOICE in the shared comparison; runtime counters then win on real evidence after a handful of routes. Structural anti-hazard: the seed magnitude must live in the PRIORITY comparison, not in the decayed-count FIELD (field separation and magnitude separation are two different bugs -- fixing one without the other still freezes the cache). Platform-scope honesty: where no observation machinery exists, keep raw rank (the source's non-Apple branch returns `remaining` unchanged). Suggest-only fix class (a magnitude clamp at the seed site). Regime: expert/weight/pin caches mixing static warm lists with observed-frequency eviction. Gain SOURCE-REPORTED (M5 Max: fixed-code SSD reads 94.65 -> 78.18 GiB, -17.4%, matching continuation scores, no routing/precision changes); honest NotBenchable here. Distinct from decayed-frequency-eviction-recency-tiebreak-route-protection (its warm-start hazard is FIELD separation -- seeding lifetime counts into the decayed field so two orderings disagree; this rule is the complementary MAGNITUDE contract in the shared comparison even with fields correctly separated -- '1 + 31*remaining/total' appears nowhere in the corpus), from fill-gate-speculation-until-working-set-resident (admission control for speculation, not eviction priority), and from host-cache-immutable-device-weights (host caching of immutable weights, no eviction namespace). Source: antirez/ds4 @ c0a6119f (MIT) -- commit 91dda0b 'Let Metal expert caching adapt beyond the built-in preload ranking' (ds4.c 15+/2-): before, the built-in preload hotlist seeded priorities at list-length magnitude (`max_entries - loaded` at 91dda0b^ ds4.c:21609, `const uint32_t priority = preload_count - loaded;` at :21727); after (pin ds4.c:21585-21594) `static uint32_t metal_graph_streaming_builtin_hotness(uint32_t remaining, uint32_t total) { ... /* List rank is a preload preference, not thousands of observed routes. */ return 1u + (uint32_t)(31ull * remaining / total); ... }`, applied at 21628-21629 and 21747-21748. Batch 123 / Plan 103 / Research 146. RIDER (Batch 129 dynamic-producer twin + measured instance, antirez/ds4 @ f62ca29a -- upstream commit b6af0ad 'Bound GLM SSD prefill cache priorities so decode can adapt', read at the upstream pin): the bounded-mapper contract applies to EVERY admission-time ranking, not just static lists -- a PREFILL-router selection score (frequency inflated by a recency bonus, '+=' of n_tokens x experts_used, millions at 100K context) was passed as the eviction-hotness priority, effectively pinning the seeded experts after long prefills and starving demand-loaded entries; the fix routes the seed priority through the SAME bounded mapper at the producer->retention hand-off seam ('priority[n] = metal_graph_streaming_builtin_hotness(target - n, target);' replacing 'priority[n++] = frequency[best];', ds4.c:46428-46433) while the inflated composite legitimately STAYS in the selection accumulator (re-map only the boundary value -- zero selection-logic change). The seam feeds TWO comparison fields (the hotness accumulator 'priority != 0 ? priority : 1u' AND the LFU count 'entries[i]->use_count = (uint64_t)priority' at ds4_metal.m:17904-17907, 17926), so one un-normalized producer corrupts both. The band ceiling must sit within the consumer's DECAYED reachable scale (observed hotness accrues 1 per route with a periodic '>>= 1' halving at ds4_metal.m:14213 -- seeds lose replaceability protection over time, not just at admission). Measured: M5 Max GLM 5.3 SSD agent decode at 100K context 0.48 -> 4.38 t/s (9.1x) with matched 128-token greedy replays IDENTICAL. OPEN RISK recorded: the rule's non-Apple carve-out arm ('return remaining' unchanged at ds4.c:21590-21592) feeds raw rank into a priority namespace whose CUDA consumer has the same comparison structure -- the 'no observation machinery exists' premise of that carve-out is UNVERIFIED, not established.".to_string(),
            ref_shape: "// the static hotlist seeds eviction priority at LIST-LENGTH magnitude:\n// observed counters top out three orders of magnitude lower, so a preload\n// entry can never be evicted by real evidence.\nfn seed_priorities(preload: &[Key], counters: &mut PriorityMap) {\n    for (rank, key) in preload.iter().enumerate() {\n        let priority = (preload.len() - rank) as u64 * 1000; // dwarfs counters\n        counters.insert(*key, priority);\n    }\n}\n".to_string(),
            opt_pattern: "// compress the seed rank into a bounded band comparable to what the\n// observation counters reach; list ORDER survives, magnitude no longer\n// out-shouts evidence.\nfn builtin_hotness(remaining: u32, total: u32) -> u32 {\n    1 + (31 * remaining / total) // 1..=31: a preference, not a dictatorship\n}\nfn seed_priorities(preload: &[Key], counters: &mut PriorityMap) {\n    let total = preload.len() as u32;\n    for (rank, key) in preload.iter().enumerate() {\n        let priority = builtin_hotness((total - rank as u32) as u32, total);\n        counters.insert(*key, u64::from(priority)); // counters can now win\n    }\n}\n".to_string(),
        },
    ]
}
